<template>
  <div class="mermaiddiagram my-4">
    <!-- eslint-disable-next-line vue/no-v-html -- SVG generated by mermaid from the bundled docs -->
    <div v-if="svg" v-html="svg" />
    <pre v-else-if="failed" class="mermaidsource">{{ code }}</pre>
    <div v-else class="text-medium-emphasis text-body-2">Loading diagram…</div>
  </div>
</template>

<script lang="ts" setup>
import { onMounted, ref } from 'vue'

// Renders a ```mermaid block from the documentation viewer
// (see utils/markdown.ts rehypeMermaid). Mermaid is large, so it is only
// loaded in the browser, the first time a diagram is shown; if a diagram
// fails to parse, its source is shown instead.
const props = defineProps<{
  /** The diagram's Mermaid source. */
  code: string
}>()

const svg = ref('')
const failed = ref(false)

let nextId = 0
let mermaidReady: Promise<typeof import('mermaid')['default']> | undefined

/**
 * Imports and initializes Mermaid once, shared by every diagram.
 *
 * @returns The initialized Mermaid API.
 */
function loadMermaid () {
  mermaidReady ??= import('mermaid').then(({ default: mermaid }) => {
    mermaid.initialize({ startOnLoad: false, securityLevel: 'strict', theme: 'default' })
    return mermaid
  })
  return mermaidReady
}

onMounted(async () => {
  try {
    const mermaid = await loadMermaid()
    const result = await mermaid.render(`mermaid-diagram-${nextId++}`, props.code)
    svg.value = result.svg
  } catch {
    failed.value = true
  }
})
</script>

<style scoped>
.mermaiddiagram {
  overflow-x: auto;
  text-align: center;
}

.mermaiddiagram :deep(svg) {
  max-width: 100%;
  height: auto;
}

.mermaidsource {
  text-align: left;
}
</style>
